<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/session.php'; require_once __DIR__ . '/includes/helpers.php'; require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/database.php'; require_login();
$statement = db()->prepare('SELECT b.*, r.name AS resource_name, GROUP_CONCAT(e.name ORDER BY e.name SEPARATOR ", ") AS extra_names FROM bookings b JOIN resources r ON r.id = b.resource_id LEFT JOIN booking_extras be ON be.booking_id = b.id LEFT JOIN extras e ON e.id = be.extra_id WHERE b.user_id = ? GROUP BY b.id ORDER BY b.booking_date DESC, b.start_time DESC'); $statement->execute([(int) current_user()['id']]); $bookings = $statement->fetchAll(); $page_title = 'Meine Buchungen'; require __DIR__ . '/includes/header.php';
?><h1>Meine Buchungen</h1><p class="lead">Hier sehen Sie ausschließlich Ihre eigenen Buchungen.</p><?php if (!$bookings): ?><div class="alert alert-info">Noch keine Buchungen vorhanden.</div><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Anlage</th><th>Datum</th><th>Uhrzeit</th><th>Extras</th><th>Status</th><th>Gesamt</th></tr></thead><tbody><?php foreach ($bookings as $booking): ?><tr><td><?= e($booking['resource_name']) ?></td><td><?= e($booking['booking_date']) ?></td><td><?= e(substr($booking['start_time'], 0, 5)) ?>–<?= e(substr($booking['end_time'], 0, 5)) ?></td><td><?= e($booking['extra_names'] ?: 'Keine') ?></td><td><span class="badge text-bg-success"><?= e($booking['status'] === 'confirmed' ? 'Bestätigt' : 'Storniert') ?></span></td><td><?= euro((float) $booking['total_price']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php require __DIR__ . '/includes/footer.php';